// Define the Random class
class Random {
  constructor() {
    this.useA = false;
    let sfc32 = function (uint128Hex) {
      let a = parseInt(uint128Hex.substring(0, 8), 16);
      let b = parseInt(uint128Hex.substring(8, 16), 16);
      let c = parseInt(uint128Hex.substring(16, 24), 16);
      let d = parseInt(uint128Hex.substring(24, 32), 16);
      return function () {
        a |= 0;
        b |= 0;
        c |= 0;
        d |= 0;
        let t = (((a + b) | 0) + d) | 0;
        d = (d + 1) | 0;
        a = b ^ (b >>> 9);
        b = (c + (c << 3)) | 0;
        c = (c << 21) | (c >>> 11);
        c = (c + t) | 0;
        return (t >>> 0) / 4294967296;
      };
    };
    // Seed prngA with first half of tokenData.hash
    this.prngA = new sfc32(tokenData.hash.substring(2, 34));
    // Seed prngB with second half of tokenData.hash
    this.prngB = new sfc32(tokenData.hash.substring(34, 66));
    for (let i = 0; i < 1e6; i += 2) {
      this.prngA();
      this.prngB();
    }
  }
  // Random number between 0 (inclusive) and 1 (exclusive)
  random_dec() {
    this.useA = !this.useA;
    return this.useA ? this.prngA() : this.prngB();
  }
  // Random number between a (inclusive) and b (exclusive)
  random_num(a, b) {
    return a + (b - a) * this.random_dec();
  }
  // Random integer between a (inclusive) and b (inclusive)
  // Requires a < b for proper probability distribution
  random_int(a, b) {
    return Math.floor(this.random_num(a, b + 1));
  }
  // Random boolean with p as percent likelihood of true
  random_bool(p) {
    return this.random_dec() < p;
  }
  // Random value in an array of items
  random_choice(list) {
    return list[this.random_int(0, list.length - 1)];
  }
}

let particles = [];
let colors = [];
let parametersPool = [
  [1.8, 0.0, 1.0, 0.1, -1.93, 5],
  [5.0, -1.0, 1.0, 0.19, -2.5, 5],
  [-1.0, 0.1, -0.82, 0.12, 1.56, 3],
  [1.81, 0.0, 1.0, 0.0, -1.81, 5],
  [10.0, -12.0, 1.0, 0.0, -2.20, 3],
  [-2.5, 0.0, 0.9, 0.0, 2.5, 3],
  [3.0, -16.79, 1.0, 0.0, -2.05, 9],
  [5.0, 1.5, 1.0, 0.0, -2.7, 6],
  [1.0, -0.1, 0.17, 0.0, -2.08, 7],
  [2.32, 0.0, 0.75, 0.0, -2.32, 5],
  [-2.0, 0.0, -0.5, 0.0, 2.6, 5],
  [2.0, 0.2, 0.1, 0.0, -2.34, 5],
  [2.0, 0.0, 1.0, 0.1, -1.86, 4],
  [-1.0, 0.1, -0.82, 0.0, 1.56, 3],
  [-1.0, 0.03, -0.8, 0.0, 1.46, 3],
  [-2.5, -0.1, 0.9, -0.15, 2.39, 16],
];
let parameters = [];
let mx = 0;
let my = 0;
let mw = 0;
let R;
let seed;

function setup() {
  R = new Random();
  seed = R.random_int(0, 99999);
  randomSeed(seed);
  parameters = parametersPool[R.random_int(0, parametersPool.length - 1)];
  noiseSeed(seed);
  createCanvas(windowWidth, windowHeight);
  background(255);

  let frame = 5000;
  if (particles.length == 0) {
    let currentPoint = [0.01, 0.01];
    for (let i = 0; i < 2000 * frame; i++) {
      let nextPoint = next(currentPoint[0], currentPoint[1]);
      mw = max(mw, currentPoint[0], currentPoint[1]);
      if (i % frame == 0) {
        particles.push(currentPoint);
      }
      currentPoint = nextPoint;
    }
  }
  mw += 0.1;

  colorMode(HSL, 100);
  let mean = R.random_num(0, 100);
  for (let i = 0; i < 10; i++) {
colors.push(abs(R.random_num(mean - 5, mean + 5)) % 100);
  }
}

function draw() {
  translate((width - height) / 2, 0);
  for (let i = 0; i < particles.length; i++) {
    let nextParticle = next(particles[i][0], particles[i][1]);
    mx = max(nextParticle[0], mx);
    my = max(nextParticle[1], my);
    let x = map(particles[i][0], -mw, mw, 0, height);
    let y = map(particles[i][1], -mw, mw, 0, height);
    fill(colors[i % colors.length], 90, 40);
    noStroke();
    circle(x, y, 1);
    particles[i] = nextParticle;
  }
}

function next(x, y) {
  let alpha = parameters[0];
  let beta = parameters[1];
  let gamma = parameters[2];
  let omega = parameters[3];
  let lambda = parameters[4];
  let degree = parameters[5];

  let imgX = x;
  let imgY = y;
  for (let i = 1; i <= degree - 2; i++) {
    let tmpX = imgX * x - imgY * y;
    let tmpY = imgY * x + imgX * y;
    imgX = tmpX;
    imgY = tmpY;
  }
  let imgZ = (alpha * (x * x + y * y) + lambda) + beta * (imgX * x - imgY * y);

  let nx = imgZ * x - omega * y + gamma * imgX;
  let ny = omega * x + imgZ * y - gamma * imgY;
  return [nx, ny];
}
